// TH14 synthetic training aliases, copied from transcribe/th14/touhou-bullets.ecl.
// Source type 10 -> target slot 10; TH14 type 0..23 keep the same number.
const TH14_SHARD: int = 512;

// TH14 v1.00b st05.ecl.txt MainSub06 entry (source lines 818-842).
// Two ECir00 batches, 10 each: batch1 spawn y=256 / volley count I0=2,
// batch2 spawn y=192 / volley count I0=3. F2=-pi/2 for both batches.
const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// Source ECir00_at ex record type 4 (ACCEL): a=120, r=1/30, s=F2-pi.
// TH16 ex-effects recipe: fixed direction at effect entry, gravity then clear.
xformdef ECIR_ACCEL(gx: fx, gy: fx) {
    @120 set_gravity(gx, gy);
    set_gravity(0fx, 0fx);
}

// Source ECir00_at lines 49-81. etAim(0,1)=fixed-direction fan, count 1/3/5/7,
// two or three volleys per enemy, 4 frames apart, speed 2.0, step 10 deg.
async sub fire_fan(volleys: int, base: angle) {
    var count: int = global(GVAR_RANK) * 2 + 1;
    var accel: fx = 1fx / 30fx;
    var gdir: angle = base - 180deg; // source s = F2 - pi
    var gx: fx = accel * cos(gdir);
    var gy: fx = accel * sin(gdir);
    wait(10);
    for v in 0..volleys {
        sh_reset(0);
        sh_sprite(0, TH14_SHARD, 6);
        sh_aim(0, 0);
        sh_count(0, count, 1);
        sh_speed(0, 2fx, 0.2fx);
        sh_angle(0, base + ((rand(3641) - 1820) as angle), 10deg);
        // ANIM a=1 entry offset: position -= 4*velocity, speed 2 -> 8px backwards.
        sh_dist(0, -8fx);
        sh_xform(0, ECIR_ACCEL(gx, gy));
        sh_fire(0);
        wait(4);
    }
}

// Source ECir00 lines 14-47 plus per-create snapshot F0/F1/I0 from MainSub06.
async sub ecir00(f0: fx, f1: fx, y0: fx, volleys: int) {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24)
    set_hitbox(8fx);   // setHitbox(16,16)
    // flagSet(15) spawn window: only bit 0x2 (no body) has a target mapping.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var r1: int = rand(65536) - 32768;
    var r2: int = rand(65536) - 32768;
    var sx: fx = 160fx + (r1 as fx) / 1024; // movePosRel: 160 + RANDF2*32
    var sy: fx = (r2 as fx) / 512;          // RANDF2*64
    move_to(0, sx, y0 + sy, EASE_LINEAR);
    move_to(160, f0, y0 + f1, EASE_QUAD_IN); // movePosRelTime(160, mode1, F0, F1)
    wait(160);
    set_enemy_flag(ENEMY_NO_BODY, 0); // flagClear(15)
    spawn fire_fan(volleys, 270deg);  // ECir00_at async; F2=-pi/2
    wait(120);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR); // moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 3fx, EASE_LINEAR);           // moveSpeedTime(120, 0, 3)
    loop { wait(1000); }
}

// Source MainSub06 lines 818-842 scheduling: 0/430 start, 10-frame spacing.
async sub pattern() {
    wait(OPENING_BUFFER);
    var y0: fx = 256fx;
    var f0: fx = -160fx;
    var f1: fx = 0fx;
    for k in 0..10 {
        f0 = f0 + 32fx;
        f1 = (rand(65536) - 32768) as fx / 1024 - 96fx; // RANDF2*32-96
        _ = spawn_enemy(0fx, y0, 160, 1, 1000, 0, ecir00(f0, f1, y0, 2));
        wait(10);
    }
    wait(330);
    y0 = 192fx;
    f0 = 160fx;
    for j in 0..10 {
        f0 = f0 - 32fx;
        f1 = (rand(65536) - 32768) as fx / 1024 - 128fx; // RANDF2*32-128
        _ = spawn_enemy(0fx, y0, 160, 1, 1000, 0, ecir00(f0, f1, y0, 3));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
